        $count = 0;

        foreach ($lines as $line) {
            $p = explode('|', $line);
            if (count($p) < 17) continue;

            [
                $name, $thc, $type, $sat, $ind, $genetics, $country,
                $taste, $effect, $aroma,
                $hIn, $yIn, $flower, $hOut, $yOut, $harvest,
                $isNew, $isPopular
            ] = $p;

            $slug = Str::slug($name);

            $seedTypeLabel = match ($type) {
                'A' => 'Автоцветущий',
                'F' => 'Феминизированный',
                'R' => 'Регулярный',
            };

            $shortDescription = "{$name} — {$seedTypeLabel} сорт от Barney's Farm. "
                . "ТГК {$thc}%. Сативы {$sat}% / Индики {$ind}%. "
                . "Урожайность в помещении: {$yIn} г/м².";

            $fullDescription = "<p><strong>{$name}</strong> — {$seedTypeLabel} сорт от Barney's Farm.</p>"
                . "<p><strong>Генетика:</strong> {$genetics}</p>"
                . "<p><strong>Страна происхождения:</strong> {$country}</p>"
                . "<p><strong>ТГК:</strong> {$thc}%</p>"
                . "<p><strong>Сативы / Индики:</strong> {$sat}% / {$ind}%</p>"
                . "<p><strong>Вкус:</strong> {$taste}</p>"
                . "<p><strong>Эффект:</strong> {$effect}</p>"
                . "<p><strong>Аромат:</strong> {$aroma}</p>"
                . "<p><strong>Высота в помещении:</strong> {$hIn} см</p>"
                . "<p><strong>Урожайность в помещении:</strong> {$yIn} г/м²</p>"
                . "<p><strong>Цветение:</strong> {$flower}</p>"
                . "<p><strong>Высота на открытом воздухе:</strong> {$hOut} см</p>"
                . "<p><strong>Урожайность на открытом воздухе:</strong> {$yOut} г с растения</p>"
                . "<p><strong>Сбор урожая:</strong> {$harvest}</p>";

            $product = Product::updateOrCreate(
                ['slug' => $slug],
                [
                    'brand_id'         => $barneys->id,
                    'name'             => $name,
                    'description'      => $shortDescription,
                    'full_description' => $fullDescription,
                    'price'            => 1500,
                    'old_price'        => null,
                    'image'            => null,
                    'gallery'          => null,
                    'is_promo'         => false,
                    'is_on_sale'       => false,
                    'seo_title'        => "{$name} купить семена | Barney's Farm",
                    'seo_description'  => "Купить семена {$name} от Barney's Farm. ТГК {$thc}%. Доставка по России.",
                    'seo_keywords'     => "{$name}, Barney's Farm, семена конопли, купить семена",
                    'thc'              => $thc . '%',
                    'taste_aroma'      => $taste,
                    'country'          => $country,
                    'effect'           => $effect,
                    'flowering'        => $flower,
                    'genetics'         => $genetics,
                    'seed_type'        => $type,
                    'height'           => $hIn . ' см',
                    'advantages'       => "Сативы {$sat}% / Индики {$ind}%",
                    'yield'            => $yIn . ' г/м²',
                    'rating'           => 4.5,
                    'stock'            => 100,
                ]
            );

            // Категория по типу
            $typeCat = match ($type) {
                'A' => $catAuto,
                'F' => $catFem,
                'R' => $catReg,
            };

            $catIds = [$typeCat->id];
            if ($isNew === '1')     $catIds[] = $catNew->id;
            if ($isPopular === '1') $catIds[] = $catPop->id;

            $product->categories()->sync($catIds);

            $count++;
        }

        $this->command->info("✅ Загружено продуктов: {$count}");
